# Print segment and nonzero tile positions from saved transform.
h=[r for r,row in enumerate(test) if len(set(row))==1 and row[0]!=0]; v=[c for c in range(len(test[0])) if len({test[r][c] for r in range(len(test))})==1 and test[0][c]!=0]
def seg(length,cuts):
 z=[];s=0
 for x in cuts:
  if s<x:z.append((s,x))
  s=x+1
 if s<length:z.append((s,length))
 return z
rs=seg(len(test),h); cs=seg(len(test[0]),v)
print(rs,cs)
def tile(i,j):
 y0,y1=rs[i];x0,x1=cs[j];return [row[x0:x1] for row in test[y0:y1]]
for i in range(4):
 print('row',i,[(j,sorted({x for row in tile(i,j) for x in row if x})) for j in range(4)])

for i,j in [(2,0),(2,1),(3,1)]:
 print((i,j)); print('\n'.join(str(row) for row in tile(i,j)))

def reflect(t,vert=False,horiz=False):
 z=[row[::-1] if horiz else row[:] for row in t]
 if vert:z=z[::-1]
 return z
for i,j in [(2,0),(2,1),(3,1)]:
 k=(i-2)*2+(j-0); print('canonical',k,reflect(tile(i,j),vert=bool(k//2),horiz=bool(k%2)))

for n,b in enumerate(bs):
 print('base',n,b)
print('diff base k3:',[(r,c,bs[0][r][c],bs[2][r][c]) for r in range(5) for c in range(5) if bs[0][r][c]!=bs[2][r][c]])
